parameters.jsCode:
// Instagram sends field 'comments'; a Facebook Page sends field 'feed' with item 'comment'
const MY_IDS = ['YOUR_IG_ACCOUNT_ID', 'YOUR_PAGE_ID']; // skip our own replies
const out = [];
for (const { json } of $input.all()) {
  for (const e of json.body?.entry || []) for (const ch of e.changes || []) {
    const v = ch.value || {};
    if (ch.field === 'comments') out.push({ platform: 'instagram', comment_id: v.id, from: v.from?.username || '', from_id: v.from?.id, text: v.text || '', post_id: v.media?.id || '' });
    if (ch.field === 'feed' && v.item === 'comment' && v.verb === 'add') out.push({ platform: 'facebook', comment_id: v.comment_id, from: v.from?.name || '', from_id: v.from?.id, text: v.message || '', post_id: v.post_id || '' });
  }
}
return out.filter(c => c.text && !MY_IDS.includes(c.from_id)).map(json => ({ json }));

